// Package loopback gives tests a loopback port that code under test will bind
// later, without the window in which anything else can take it (DEVDESK-35).
//
// It imports testing and is meant to be imported from _test.go files only, so
// it never reaches the production binary.
package loopback
package loopback

import (
	"syscall"
	"testing"
)

// ReservePort binds a socket to 127.0.0.1:0 with SO_REUSEADDR and keeps it
// bound, but not listening, until the test ends.
//
// On Linux that is a reservation the kernel honors: neither bind(0) nor
// connect() hands out a port such a socket holds, in this process or any
// other, while an explicit bind with SO_REUSEADDR followed by listen — what
// net.Listen does, so what the code under test does — still succeeds, since at
// most one of the sockets sharing the port listens. Nothing is released before
// the code under test binds, so there is no window to lose the port in, and two
// reservations held at once can never return the same port.
func ReservePort(t testing.TB) int {
	t.Helper()
	fd, err := syscall.Socket(syscall.AF_INET, syscall.SOCK_STREAM|syscall.SOCK_CLOEXEC, 0)
	if err != nil {
		t.Fatalf("reserving a port: %v", err)
	}
	t.Cleanup(func() { _ = syscall.Close(fd) })
	if err := syscall.SetsockoptInt(fd, syscall.SOL_SOCKET, syscall.SO_REUSEADDR, 1); err != nil {
		t.Fatalf("reserving a port: %v", err)
	}
	if err := syscall.Bind(fd, &syscall.SockaddrInet4{Addr: [4]byte{127, 0, 0, 1}}); err != nil {
		t.Fatalf("reserving a port: %v", err)
	}
	sa, err := syscall.Getsockname(fd)
	if err != nil {
		t.Fatalf("reading the reserved port: %v", err)
	}
	return sa.(*syscall.SockaddrInet4).Port
}
package loopback

import (
	"errors"
	"net"
	"strconv"
	"syscall"
	"testing"
)

// TestAReservedPortStaysOccupiedYetCanBeListenedOn is DEVDESK-35's
// regression test. A reserved port must still occupy the kernel's bind table —
// that table is what bind(0) and connect() consult when they pick a port, so a
// port absent from it can be given to anyone before the code under test binds
// it. A bind without SO_REUSEADDR is the observable: it fails on an occupied
// port and succeeds on a released one. And net.Listen must still take it.
func TestAReservedPortStaysOccupiedYetCanBeListenedOn(t *testing.T) {
	port := ReservePort(t)

	fd, err := syscall.Socket(syscall.AF_INET, syscall.SOCK_STREAM|syscall.SOCK_CLOEXEC, 0)
	if err != nil {
		t.Fatal(err)
	}
	defer func() { _ = syscall.Close(fd) }()
	err = syscall.Bind(fd, &syscall.SockaddrInet4{Port: port, Addr: [4]byte{127, 0, 0, 1}})
	if !errors.Is(err, syscall.EADDRINUSE) {
		t.Fatalf("binding the reserved port %d answered %v, want EADDRINUSE: the port is up for grabs", port, err)
	}

	ln, err := net.Listen("tcp", "127.0.0.1:"+strconv.Itoa(port))
	if err != nil {
		t.Fatalf("net.Listen refused the reserved port: %v", err)
	}
	_ = ln.Close()
}

